Here is the idiomatic Python implementation of Quicksort ($O(n \log n)$) and Binary Search ($O(\log n)$):

```python
from typing import List, Any

def quicksort(arr: List[Any]) -> List[Any]:
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

def binary_search(sorted_arr: List[Any], target: Any) -> int:
    low, high = 0, len(sorted_arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if sorted_arr[mid] == target:
            return mid
        elif sorted_arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

if __name__ == "__main__":
    data = [29, 10, 14, 37, 13]
    sorted_data = quicksort(data)
    print("Sorted:", sorted_data)
    print("Index of 14:", binary_search(sorted_data, 14))
```
